    $cfgPath = Join-Path $Root "data/meeting-topics.json"
    if (-not (Test-Path -LiteralPath $cfgPath)) { return @() }
    try { $cfg = Get-Content -Raw -LiteralPath $cfgPath | ConvertFrom-Json }
    catch { Write-Host "meeting-topics.json unreadable; skipping auto-tag."; return @() }

    $minHits = if ($cfg.minHits) { [int]$cfg.minHits } else { 2 }
    $lower = $Text.ToLowerInvariant()
    $hits = New-Object System.Collections.Generic.List[string]

    foreach ($t in @($cfg.topics)) {
        $n = 0
        foreach ($m in @($t.match)) {
            $needle = ([string]$m).ToLowerInvariant()
            if ([string]::IsNullOrWhiteSpace($needle)) { continue }
            # count occurrences, not just presence — repetition is the signal
            # that a topic was discussed rather than name-dropped once
            $idx = 0
            while (($idx = $lower.IndexOf($needle, $idx)) -ge 0) { $n++; $idx += $needle.Length }
        }
        if ($n -ge $minHits) { $hits.Add([string]$t.tag) }
    }
    return @($hits)
}

function Invoke-MeetingSync {
    param([string]$VaultDir = "/Users/kristinarash/SecondBrain/Inbox/meetings")

    Show-Section "Meeting Sync"
    $ff = Get-Command fireflies-pp-cli -ErrorAction SilentlyContinue
    if (-not $ff) { Write-Host "fireflies-pp-cli not found on PATH; skipped."; return $null }

    $vaultDir = $VaultDir
    New-Item -ItemType Directory -Force -Path $vaultDir | Out-Null
    $statePath = Join-Path $vaultDir ".sync-state.json"
    if (-not (Test-Path -LiteralPath $statePath)) {
        '{"exports":{}}' | Set-Content -LiteralPath $statePath -Encoding UTF8
    }
